class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        def get_first_digit(n: int) -> int:
            return int(str(n)[0])

        def get_last_digit(n: int) -> int:
            return n % 10

        def gcd(a: int, b: int) -> int:
            while b:
                a, b = b, a % b
            return a

        def is_coprime(a: int, b: int) -> bool:
            return gcd(a, b) == 1

        # Pre-calculate the first digits and last digits for all numbers in nums
        first_digits = [get_first_digit(n) for n in nums]
        last_digits = [get_last_digit(n) for n in nums]

        count = 0
        n = len(nums)
        for i in range(n):
            for j in range(i + 1, n):
                # Check if the pair (i, j) is beautiful
                if is_coprime(first_digits[i], last_digits[j]):
                    count += 1

