class Solution:
    def findPrimePairs(self, n: int) -> List[List[int]]:
        # Step 1: Sieve of Eratosthenes to find all primes up to n
        # We need primes up to n, but since x + y = n and x <= y, 
        # the maximum value for x is n/2. So we only need primes up to n.
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False

        for p in range(2, int(n**0.5) + 1):
            if is_prime[p]:
                for i in range(p * p, n + 1, p):
                    is_prime[i] = False

        # Step 2: Find all prime pairs [x, y] such that 1 <= x <= y <= n, x + y == n, x and y are prime
        result = []
        # Iterate through all possible values of x from 2 up to n/2
        # Since x and y must be prime, x >= 2.
        # Since x + y = n and x <= y, we have x + x <= x + y = n, so 2x <= n, x <= n/2.
        for x in range(2, n // 2 + 1):
            if is_prime[x]:
                y = n - x
                if y >= x:
                    if is_prime[y]:
                        # We already ensured y <= n because x >= 2, so y = n - x <= n - 2.
                        # Since x >= 2, y = n - x <= n - 2.
                        # The condition y >= x is already handled by the loop range x <= n // 2.
                        # If x = n/2 (and n is even), y = n/2, so y >= x holds.
                        result.append([x, y])

        # Step 3: Return the result (it should already be sorted by x because we iterated in increasing order of x)
        return result

