class Solution:
    def countSymmetricIntegers(self, low: int, high: int) -> int:
        def is_symmetric(n: int) -> bool:
            s = str(n)
            length = len(s)
            if length % 2 != 0:
                return False

            n_half = length // 2
            first_half = s[:n_half]
            second_half = s[n_half:]

            sum_first = sum(int(d) for d in first_half)
            sum_first_digits = sum(int(d) for d in second_half)

            return sum_first == sum_first_digits

        count = 0
        for i in range(low, high + 1):
            if is_symmetric(i):
                count += 1
        return count
