        n = len(nums)
        min_sum = float('inf')
        found = False

        # Iterate through all possible middle elements j
        for j in range(1, n - 1):
            # Iterate through all possible left elements i < j
            for i in range(j):
                # Check if nums[i] < nums[j]
                if nums[i] < nums[j]:
                    # Iterate through all possible right elements k > j
                    for k in range(j + 1, n):
                        # Check if nums[k] < nums[j]
                        if nums[k] < nums[j]:
                            # We found a mountain triplet (i, j, k)
                            current_sum = nums[i] + nums[j] + nums[k]
                            min_sum = min(min_sum, current_sum)
                            found = True

        if found:
            return min_sum
        else:
