    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return n

        max_len = 1

        for i in range(n - 1):
            # Check for strictly increasing subarray starting at i
            if nums[i] < nums[i+1]:
                current_increasing_len = 1
                j = i
                while j < n - 1 and nums[j] < nums[j+1]:
                    current_increasing_len += 1
                    j += 1
                max_len = max(max_len, current_increasing_len)

            # Check for strictly decreasing subarray starting at i
            if nums[i] > nums[i+1]:
                current_decreasing_len = 1
                j = i
                while j < n - 1 and nums[j] > nums[j+1]:
                    current_decreasing_len += 1
                    j += 1
                max_len = max(max_len, current_decreasing_len)

        return max_len
