    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Step 1: Find all indices where x appears in nums
        indices_of_x = []
        for i, num in enumerate(nums):
            if num == x:
                indices_of_x.append(i)

        # Step 2: Process queries
        results = []
        for q in queries:
            # q is the k-th occurrence we are looking for
            # The index in indices_of_x is q - 1 (since indices are 0-based)
            target_index_in_indices = q - 1

            # Check if the q-th occurrence exists
            if target_index_in_indices < len(indices_of_x):
                # If it exists, return the index stored in indices_of_x
                results.append(indices_of_x[target_index_in_indices])
            else:
                # If it doesn't exist, return -1
                results.append(-1)

