class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        # Step 1: Identify all possible valid strings (prefixes of words)
        valid_strings = set()
        for word in words:
            for i in range(1, len(word) + 1):
                valid_strings.add(word[:i])

        # Step 2: Dynamic Programming to find the minimum number of valid strings
        n = len(target)
        # dp[i] will store the minimum number of valid strings to form target[:i]
        # Initialize with infinity, dp[0] = 0
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Pre-calculate the set of valid strings for faster lookup (optional but good practice)
        # Since the number of valid strings can be large, we'll use the set directly in the loop

        for i in range(1, n + 1):
            for j in range(i):
                # Consider the substring target[j:i] as the last valid string
                substring = target[j:i]

                # Check if substring is a valid string
                if substring in valid_strings:
                    # If it is, we can potentially update dp[i]
                    if dp[j] != float('inf'):
                        dp[i] = min(dp[i], dp[j] + 1)

        # Step 3: Return the result
        if dp[n] == float('inf'):
            return -1
        else:
            return dp[n]

